#include <cassert>
#include <string>
#include <string_view>

int main() {
    using namespace std::literals;

    const auto str = "Hello, C++20!"s;

    assert("" && str.ends_with("C++20!"sv) // (1)
        && !str.ends_with("c++20!"sv)      // (1)
        && str.ends_with("C++20!"s)  // (1) implicit conversion string to string_view
        && !str.ends_with("c++20!"s) // (1) implicit conversion string to string_view
        && str.ends_with('!')        // (2)
        && !str.ends_with('?')       // (2)
        && str.ends_with("C++20!")   // (3)
        && !str.ends_with("c++20!")  // (3)
    );
}

